import { referenceTheme } from './generated'
import { builtinTokens } from '../../generated/tokens'
import { contrastRatio } from '../../theme/contrast'
import type { ResolvedTheme, ThemeRole } from '../../theme/types'

interface Slot {
  readonly key: string
  readonly role: ThemeRole
  readonly raw: string
  readonly background?: string
  readonly minimum?: number
}
const slots: Readonly<Record<string, Slot>> = referenceTheme.slots
export interface ReferenceStyleProjection {
  readonly colors: Readonly<Record<string, string>>
  readonly repairs: readonly {
    readonly slot: string
    readonly original: string
    readonly effective: string
  }[]
}
function composite(raw: string, background?: string): string {
  let hex = raw.slice(1)
  if (hex.length < 5) hex = [...hex].map((char) => char + char).join('')
  if (hex.length === 6) return '#' + hex.toUpperCase()
  if (hex.length !== 8 || !background) throw Error('Unbound reference alpha')
  const alpha = parseInt(hex.slice(6), 16) / 255
  return (
    '#' +
    [0, 2, 4]
      .map((offset) =>
        Math.round(
          parseInt(hex.slice(offset, offset + 2), 16) * alpha +
            parseInt(background.slice(offset + 1, offset + 3), 16) * (1 - alpha),
        )
          .toString(16)
          .padStart(2, '0'),
      )
      .join('')
      .toUpperCase()
  )
}
/** First-party view projection, after the existing resolver; it never selects or persists a theme. */
export function projectReferenceStyles(snapshot: ResolvedTheme): ReferenceStyleProjection {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) return { colors: {}, repairs: [] }
  const colors: Record<string, string> = {},
    active = new Set<string>()
  const repairs: { slot: string; original: string; effective: string }[] = []
  const resolve = (name: string): string => {
    if (colors[name]) return colors[name]
    if (active.has(name) || !Object.hasOwn(slots, name))
      throw Error('Invalid reference style dependency')
    active.add(name)
    const slot = slots[name],
      background = slot.background ? resolve(slot.background) : undefined
    const roleChanged = snapshot.colors[slot.role] !== referenceTheme.descriptor.colors[slot.role]
    let color = roleChanged ? snapshot.colors[slot.role] : composite(slot.raw, background)
    if (background && slot.minimum && contrastRatio(color, background) < slot.minimum) {
      const original = color
      const replacement = [
        snapshot.colors[slot.role],
        builtinTokens.themes.dark[slot.role],
        builtinTokens.themes.dark['text.primary'],
        builtinTokens.themes.light['text.primary'],
      ].find((candidate) => contrastRatio(candidate, background) >= slot.minimum!)
      if (!replacement) throw Error('Reference style contrast cannot be established: ' + name)
      color = replacement
      repairs.push({ slot: name, original, effective: color })
    }
    active.delete(name)
    colors[name] = color
    return color
  }
  for (const name of Object.keys(slots)) resolve(name)
  return { colors: Object.freeze(colors), repairs: Object.freeze(repairs) }
}

export function applyReferencePreset(root: HTMLElement, snapshot: ResolvedTheme): void {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) {
    if (root.dataset.fradeReference === 'vscode-dark-2026') {
      root.removeAttribute('data-frade-reference')
      for (const name of Object.keys(slots)) root.style.removeProperty('--frade-vscode-' + name)
    }
    return
  }
  const projection = projectReferenceStyles(snapshot)
  for (const [name, color] of Object.entries(projection.colors))
    root.style.setProperty('--frade-vscode-' + name, color)
  root.dataset.fradeReference = 'vscode-dark-2026'
}

import { referenceTheme } from '../reference/vscode-dark-2026/generated'
import { builtinTokens } from '../generated/tokens'
import { isHexColor, themeRoles } from './contrast'
import { freezeOwned } from './types'
import type { RegisteredTheme, ThemeRegistry, ThemeIssue, ThemeKind, ThemeRole } from './types'

export const BUILTIN_IDS = Object.freeze({
  light: 'frade.builtin/light',
  dark: 'frade.builtin/dark',
  'high-contrast': 'frade.builtin/high-contrast',
})
export const themeKinds: readonly ThemeKind[] = Object.freeze(['light', 'dark', 'high-contrast'])
const labels: Record<ThemeKind, string> = {
  light: 'Frade Light',
  dark: 'Frade Dark',
  'high-contrast': 'Frade High Contrast',
}
const roles = new Set<string>(themeRoles)
export function isDataRecord(value: unknown): value is Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false
  const prototype = Object.getPrototypeOf(value)
  return (
    (prototype === Object.prototype || prototype === null) &&
    Object.values(Object.getOwnPropertyDescriptors(value)).every((d) => 'value' in d)
  )
}
export function issue(code: string, source: string, message: string, role?: string): ThemeIssue {
  return role === undefined ? { code, source, message } : { code, source, message, role }
}
/** Native descriptors accept data only. This is an in-memory registry, not an installer. */
export function validateColors(
  value: unknown,
  source: string,
): {
  colors: Partial<Record<ThemeRole, string>>
  issues: ThemeIssue[]
  recognized: string[]
  ignored: string[]
} {
  const colors: Partial<Record<ThemeRole, string>> = {},
    issues: ThemeIssue[] = [],
    recognized: string[] = [],
    ignored: string[] = []
  if (!isDataRecord(value))
    return {
      colors,
      issues: [issue('INVALID_COLORS', source, 'Colors must be a plain data record')],
      recognized,
      ignored,
    }
  for (const role of themeRoles)
    if (Object.hasOwn(value, role)) {
      if (isHexColor(value[role])) {
        colors[role] = value[role]
        recognized.push(role)
      } else {
        issues.push(issue('INVALID_COLOR', source, 'Known roles require HEX6 values', role))
        ignored.push(role)
      }
    }
  for (const role of Object.keys(value)
    .filter((key) => !roles.has(key))
    .sort()) {
    issues.push(issue('UNKNOWN_ROLE', source, 'Unregistered role ignored', role))
    ignored.push(role)
  }
  return { colors, issues, recognized, ignored }
}
export function createThemeRegistry(descriptors: readonly unknown[] = []): ThemeRegistry {
  const entries = new Map<string, RegisteredTheme>(),
    issues: ThemeIssue[] = []
  for (const kind of themeKinds)
    entries.set(
      BUILTIN_IDS[kind],
      freezeOwned({
        id: BUILTIN_IDS[kind],
        label: labels[kind],
        kind,
        enabled: true,
        builtin: true,
        colors: { ...builtinTokens.themes[kind] },
        issues: [],
      }),
    )
  for (const [index, descriptor] of descriptors.entries()) {
    const source = 'descriptor[' + index + ']'
    if (!isDataRecord(descriptor)) {
      issues.push(issue('INVALID_DESCRIPTOR', source, 'Theme must be a plain data record'))
      continue
    }
    if (typeof descriptor.id === 'string' && descriptor.id.startsWith('frade.builtin/')) {
      issues.push(issue('RESERVED_ID', source, 'Builtin identity cannot be replaced'))
      continue
    }
    if (
      typeof descriptor.id !== 'string' ||
      descriptor.id.length > 160 ||
      !/^[a-z0-9][a-z0-9.-]*\.[a-z0-9][a-z0-9.-]*[/][a-z0-9][a-z0-9._-]*$/i.test(descriptor.id) ||
      typeof descriptor.label !== 'string' ||
      descriptor.label.length < 1 ||
      descriptor.label.length > 160 ||
      [...descriptor.label].some(
        (character) => character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127,
      ) ||
      !themeKinds.includes(descriptor.kind as ThemeKind) ||
      (descriptor.enabled !== undefined && typeof descriptor.enabled !== 'boolean') ||
      Object.keys(descriptor).some(
        (key) => !['id', 'label', 'kind', 'enabled', 'colors'].includes(key),
      ) ||
      !isDataRecord(descriptor.colors)
    ) {
      issues.push(
        issue('INVALID_DESCRIPTOR', source, 'Invalid theme identity, kind, label or data fields'),
      )
      continue
    }
    if (entries.has(descriptor.id)) {
      issues.push(issue('DUPLICATE_ID', source, 'First registered stable identity wins'))
      continue
    }
    const validated = validateColors(descriptor.colors, descriptor.id)
    issues.push(...validated.issues)
    entries.set(
      descriptor.id,
      freezeOwned({
        id: descriptor.id,
        label: descriptor.label,
        kind: descriptor.kind as ThemeKind,
        enabled: descriptor.enabled !== false,
        builtin: false,
        colors: validated.colors,
        issues: validated.issues,
      }),
    )
  }
  const list = freezeOwned([...entries.values()]),
    diagnostics = freezeOwned(issues)
  return Object.freeze({
    issues: diagnostics,
    get: (id: string) => entries.get(id),
    list: () => list,
  })
}

/** Application opt-in: the pure core registry's three-builtin contract stays unchanged. */
export function createApplicationThemeRegistry(descriptors: readonly unknown[] = []): ThemeRegistry {
  return createThemeRegistry([referenceTheme.descriptor, ...descriptors])
}
