  }
  button.addEventListener('click', async () => {
    if (!recover || button.disabled) return
    button.disabled = true
    try {
      await recover()
    } catch (error) {
      status.textContent =
        'Восстановление не выполнено: ' + (error instanceof Error ? error.message : String(error))
