    paint: async () => {
      cover()
      button.hidden = true
      status.textContent = 'Обновление интерфейса…'
      await paint()
    },
    reveal: () => {
      curtain.hidden = true
      for (const [element, wasInert] of inert) if (!wasInert) element.removeAttribute('inert')
