test('VS2026 JSONC include inheritance, cycles and traversal are explicit', () => {
  const files = {
    '2026-dark.json':
      '{ "include":"./dark_modern.json", "colors":{"sample":"#121314",}, /* source comment */ }',
    'dark_modern.json': '{ "include":"./dark_plus.json", "colors":{"sample":"#222222"} }',
    'dark_plus.json':
      '{ "include":"./dark_vs.json", "tokenColors":[{"scope":"test","settings":{"foreground":"#abcdef"}}] }',
    'dark_vs.json': '{ "colors":{"base":"#010203"} }',
  }
  const parsed = parseSourceClosure(files)
  assert.equal(parsed.colors.sample, '#121314')
  assert.equal(parsed.colors.base, '#010203')
  assert.equal(parsed.tokenColors.length, 1)
  assert.throws(
    () => parseSourceClosure({ ...files, '2026-dark.json': '{"include":"../private.json"}' }),
    /UNSAFE_REFERENCE_INCLUDE/,
  )
  assert.throws(
    () => parseSourceClosure({ ...files, 'dark_vs.json': '{"include":"./2026-dark.json"}' }),
    /CYCLIC_REFERENCE_INCLUDE/,
  )
})

